-- Per-interview question mix and personalised questions.
-- Personalised questions generated by the admin's free local AI are stored in
-- the question bank but tied to ONE invitation (invitation_id) and never used
-- for anyone else. Template-based questions are labelled 'template', never AI.

alter type public.question_origin add value if not exists 'template';

alter table public.question_bank
  add column if not exists invitation_id uuid references public.interview_invitations (id) on delete cascade,
  add column if not exists ai_kind text check (ai_kind is null or ai_kind in ('personal', 'course')),
  add column if not exists ai_model text;
create index if not exists question_bank_invitation_idx on public.question_bank (invitation_id) where invitation_id is not null;

alter table public.interview_invitations
  add column if not exists bank_question_count integer check (bank_question_count is null or bank_question_count between 0 and 40),
  add column if not exists personal_question_count integer check (personal_question_count is null or personal_question_count between 0 and 20),
  add column if not exists course_question_count integer check (course_question_count is null or course_question_count between 0 and 20),
  add column if not exists personalised_at timestamptz,
  add column if not exists personalised_model text;
alter table public.interview_invitations drop constraint if exists interview_invitations_question_count_check;
alter table public.interview_invitations add constraint interview_invitations_question_count_check
  check (question_count is null or question_count between 1 and 60);

alter table public.interview_sessions drop constraint if exists interview_sessions_generation_mode_check;
alter table public.interview_sessions add constraint interview_sessions_generation_mode_check
  check (generation_mode in ('bank_and_ai', 'bank_only', 'bank_and_template', 'bank_ai_template'));

-- Course reference documents (admin-uploaded; private storage under courses/<course_id>/).
create table if not exists public.course_documents (
  id uuid primary key default gen_random_uuid(),
  course_id uuid not null references public.courses (id) on delete cascade,
  storage_path text not null unique check (storage_path like 'courses/%'),
  file_name text not null check (char_length(file_name) <= 255),
  mime_type text not null,
  size_bytes integer not null check (size_bytes > 0 and size_bytes <= 10485760),
  created_at timestamptz not null default now()
);
alter table public.course_documents enable row level security;
create policy course_documents_admin on public.course_documents for all to authenticated using (public.is_admin()) with check (public.is_admin());
grant select, insert, update, delete on public.course_documents to authenticated, service_role;

drop policy if exists "invitation documents: admin insert" on storage.objects;
create policy "documents: admin insert" on storage.objects for insert to authenticated
  with check (bucket_id = 'student-documents' and public.is_admin() and (storage.foldername(name))[1] in ('invitations', 'courses'));

insert into public.admin_settings (key, value)
values ('default_question_mix', '{"total": 15, "bank": 9, "personal": 4, "course": 2}'::jsonb)
on conflict (key) do nothing;

-- Creation now also stores the question mix.
create or replace function public.admin_create_invitation(p jsonb) returns table (id uuid, token text)
language plpgsql security definer set search_path = public, extensions, vault as $$
declare
  v_token text := public.new_invitation_token();
  v_id uuid := gen_random_uuid();
  v_secret uuid;
begin
  if not public.is_admin() then raise exception 'admins only'; end if;
  v_secret := vault.create_secret(v_token, 'invitation-' || v_id::text, 'Interview invitation link token', null);
  insert into public.interview_invitations (
    id, token_hash, token_secret_id, student_name, student_ref, university_id, course_id, template_id,
    question_count, ai_question_count, bank_question_count, personal_question_count, course_question_count,
    prep_seconds, answer_seconds, submission_mode, allow_early_submit,
    previous_qualification, expires_at, max_attempts, created_by)
  values (
    v_id, public.hash_invitation_token(v_token), v_secret,
    trim(p->>'student_name'), trim(p->>'student_ref'),
    (p->>'university_id')::uuid, (p->>'course_id')::uuid, nullif(p->>'template_id', '')::uuid,
    nullif(p->>'question_count', '')::int, nullif(p->>'ai_question_count', '')::int,
    nullif(p->>'bank_question_count', '')::int, nullif(p->>'personal_question_count', '')::int, nullif(p->>'course_question_count', '')::int,
    nullif(p->>'prep_seconds', '')::int, nullif(p->>'answer_seconds', '')::int,
    nullif(p->>'submission_mode', '')::public.submission_mode, (p->>'allow_early_submit')::boolean,
    nullif(trim(p->>'previous_qualification'), ''),
    now() + make_interval(days => greatest(1, least(365, coalesce((p->>'expires_in_days')::int, 14)))),
    greatest(1, least(20, coalesce((p->>'max_attempts')::int, 1))),
    auth.uid());
  return query select v_id, v_token;
end $$;
